// ?d_00198f00@@YAXXZ
// partial score=0.5267 date=2026-09-30
// Vector node storage and the auto-inlined container release reproduce retail's loop registers.
// Residue: the inlined AsciiString::compare at +0xDE keeps thatLen in memory, not ESI (6 bytes).
// ?removeOwnedTeams@SideTeams00198F00@@QAEXH@Z
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc /D_STLP_USE_STATIC_LIB /Igame/Libraries/Source/WWVegas/WWLib
// stlport

typedef int Int;
typedef bool Bool;

#include "ascii_string.h"
#include <vector>
enum NameKeyType { NAMEKEY_INVALID = 0 };
class StaticNameKey { public: NameKeyType key() const; };
class Dict {
    void *m_data;
public:
    enum DataType { DICT_NONE=-1, DICT_BOOL, DICT_INT, DICT_REAL, DICT_ASCIISTRING };
    DataType getType(NameKeyType key) const;
    AsciiString getAsciiString(NameKeyType key, bool *exists) const;
    void clear();
};
class Gen0035B3A0
{
public:
	void cleanup(void);
};

class BfmeMapObjectExtra
{
public:
	void bfmeReset(void);
};

struct BfmeTeamInfoSlot
{
	short m_next;
	short m_previous;
	short m_reserved;
	short m_free;
	Int m_generation;
	Dict m_dict;
};

typedef char BfmeTeamInfoSlotSizeCheck[
	(sizeof(BfmeTeamInfoSlot) == 0x10) ? 1 : -1];

class BfmeIndexedNodesFM
{
public:
	void bfmePrepareRelease(int index);
	// Retail keeps an out-of-line copy at 0x001977F0 and inlines it here.
	void bfmeRelease(int index)
	{
		bfmePrepareRelease(index);
		BfmeTeamInfoSlot *nodes = m_nodes.begin();
		nodes[index].m_dict.clear();
		m_nodes[nodes[index].m_next].m_previous = nodes[index].m_previous;
		m_nodes[nodes[index].m_previous].m_next = nodes[index].m_next;
		short oldFreeHead = m_freeHead;
		--m_count;
		nodes[index].m_next = oldFreeHead;
		m_freeHead = static_cast<short>(index);
	}

	char m_tree[0x0c];
	// Vector of 16-byte records, as in Rva0019B850TeamRecUpdate.cpp.
	_STL::vector<BfmeTeamInfoSlot> m_nodes;
	short m_count;
	short m_freeHead;
};

typedef char BfmeIndexedNodesFMSizeCheck[
	(sizeof(BfmeIndexedNodesFM) == 0x1c) ? 1 : -1];

struct BfmeSidesInfo
{
	void *m_pBuildList;
	Dict m_dict;
	Gen0035B3A0 *m_scripts;
	char m_tail[0x0c];
};

typedef char BfmeSidesInfoSizeCheck[
	(sizeof(BfmeSidesInfo) == 0x18) ? 1 : -1];

class SideTeams00198F00
{
public:
	void removeOwnedTeams(int index);
	BfmeSidesInfo *getSideInfo(int side)
	{
		if (side >= 0 && side < m_numSides)
			return &m_sides[side];
		return 0;
	}

private:
	char m_prefix[0x28];
	int m_numSides;
	BfmeSidesInfo m_sides[32];
	int m_numSkirmishSides;
	BfmeSidesInfo m_skirmishSides[32];
	BfmeIndexedNodesFM m_teamrec;
};

extern StaticNameKey TheKey_teamLibraryMapName;
class GenKey { public: int fetch(); };
extern GenKey GenKey0012A7918;
extern StaticNameKey TheKey_teamOwner;

// ?removeOwnedTeams@SideTeams00198F00@@QAEXH@Z
void SideTeams00198F00::removeOwnedTeams(int index)
{
	BfmeSidesInfo *side = getSideInfo(index);

	if (side->m_scripts != 0)
		side->m_scripts->cleanup();

	AsciiString sideName =
		side->m_dict.getAsciiString(static_cast<NameKeyType>(GenKey0012A7918.fetch()), 0);

	for (int teamIndex = m_teamrec.m_nodes[0].m_next; teamIndex != 0; )
	{
		int nextTeam = m_teamrec.m_nodes[teamIndex].m_next;
		Dict *dict = &m_teamrec.m_nodes[teamIndex].m_dict;
		if (dict->getType(TheKey_teamLibraryMapName.key()) == Dict::DICT_ASCIISTRING &&
			dict->getAsciiString(TheKey_teamOwner.key(), 0).compare(sideName) == 0)
			m_teamrec.bfmeRelease(teamIndex);
		teamIndex = nextTeam;
	}
}
